/**
 * The Cargora mark, as SVG, so the sign-in screen shows the same thing as the home-screen
 * icon rather than a letter that happens to also be a C.
 *
 * Same geometry as assets/icon.png (generated by the icon script): a ring with a wedge
 * removed, and a corrugated container sitting in the gap.
 */
import React from "react";
import Svg, { Defs, G, LinearGradient, Path, Rect, Stop } from "react-native-svg";

/**
 * @param size   overall square size
 * @param tile   draws the gradient tile behind the mark (as the app icon has); false gives
 *               just the mark, for use on a surface that already has its own colour
 */
export function Logo({
  size = 64,
  tile = true,
  markColor = "#FFFFFF",
}: {
  size?: number;
  tile?: boolean;
  markColor?: string;
}) {
  // Drawn in a 100x100 space and scaled by the viewBox, so every number below is a
  // percentage and the mark stays identical at 32px and at 512px.
  const R_OUT = 33;
  const R_IN = 21.5;

  /** The C: an annulus with a 84-degree wedge taken out of its right-hand side. Built as a
   *  single path with two arcs rather than a stroked circle, because a stroke cannot be
   *  given a gap without dash arithmetic that breaks at different sizes. */
  const ringPath = (() => {
    const start = 42;   // degrees, measured from east
    const end = 318;
    const rad = (d: number) => (d * Math.PI) / 180;
    const p = (r: number, d: number) =>
      `${50 + r * Math.cos(rad(d))} ${50 + r * Math.sin(rad(d))}`;
    return [
      `M ${p(R_OUT, start)}`,
      `A ${R_OUT} ${R_OUT} 0 1 1 ${p(R_OUT, end)}`,
      `L ${p(R_IN, end)}`,
      `A ${R_IN} ${R_IN} 0 1 0 ${p(R_IN, start)}`,
      "Z",
    ].join(" ");
  })();

  const boxW = R_OUT * 0.62;
  const boxH = R_OUT * 0.42;
  const boxX = 50 + R_OUT * 0.02;
  const boxY = 50 - boxH / 2;

  return (
    <Svg width={size} height={size} viewBox="0 0 100 100">
      <Defs>
        <LinearGradient id="cargoraTile" x1="0" y1="0" x2="1" y2="1">
          <Stop offset="0" stopColor="#4F46E5" />
          <Stop offset="0.5" stopColor="#6366F1" />
          <Stop offset="1" stopColor="#5B6CF9" />
        </LinearGradient>
      </Defs>

      {tile ? <Rect x="0" y="0" width="100" height="100" rx="23" fill="url(#cargoraTile)" /> : null}

      <G>
        <Path d={ringPath} fill={markColor} fillRule="evenodd" />
        <Rect x={boxX} y={boxY} width={boxW} height={boxH} fill={markColor} />
        {/* Four ribs, cut back out of the container so it reads as corrugated metal. Two
            thick bars would read as a pause button. */}
        {[0.26, 0.42, 0.58, 0.74].map((f) => (
          <Rect
            key={f}
            x={boxX + boxW * f - boxW * 0.03}
            y={boxY + boxH * 0.18}
            width={boxW * 0.06}
            height={boxH * 0.64}
            fill={tile ? "#5B6CF9" : "transparent"}
            opacity={tile ? 1 : 0}
          />
        ))}
      </G>
    </Svg>
  );
}
